import numpy as np
one=np.ones_like(x)
core=[one,x,v,x**2,x**3,x*v,v**2,v**3,x**2*v,x*v**2]
def fitc(cols):
    A=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    return np.mean((dv_dt-A@c)**2)/np.var(dv_dt)
ws=np.linspace(0.05,1.2,116)
best=(1,None)
for w1 in ws:
    for w2 in ws:
        if w2<=w1: continue
        n=fitc(core+[np.cos(w1*t),np.sin(w1*t),np.cos(w2*t),np.sin(w2*t)])
        if n<best[0]: best=(n,(w1,w2))
print(best)
